size_t RegisterJPEGImage(void) {
    MagickInfo
        *magick_info;

    char
        *version;

    size_t
        signature;

    version = ConstantString(MAGICKCORE_JPEG_VERSION);
    magick_info = (MagickInfo *) AcquireMagickMemory(sizeof(*magick_info));
    magick_info->signature = MagickSignature;
    magick_info->decoder = JPEGReadImage;
    magick_info->encoder = JPEGWriteImage;
    magick_info->thread_support = MagickTrue;
    magick_info->mime_type = ConstantString("image/jpeg");
    magick_info->description = ConstantString("JPEG image format");
    magick_info->extension = ConstantString("JPE");
    magick_info->extension = ConstantString("JPEG");
    magick_info->extension = ConstantString("JPG");
    magick_info->extension = ConstantString("JPS");
    magick_info->extension = ConstantString("PJPEG");

    if ((IsStringEqual(version,"6b") != MagickFalse) ||
        (IsStringEqual(version,"62") != MagickFalse) ||
        (IsStringEqual(version,"7") != MagickFalse) ||
        (IsStringEqual(version,"8") != MagickFalse) ||
        (IsStringEqual(version,"9") != MagickFalse))
    {
        magick_info->thread_support = MagickTrue;
    }

    if (RegisterMagickInfo(magick_info) == MagickFalse)
    {
        magick_info = (MagickInfo *) RelinquishMagickMemory(magick_info);
        return(0);
    }

    signature = magick_info->signature;
    magick_info = (MagickInfo *) RelinquishMagickMemory(magick_info);

    return(signature);
}

