size_t RegisterJPEGImage(void) {
    MagickInfo
        *magick_info;

    MagickInfo
        *entry;

    size_t
        length;

    magick_info = (MagickInfo *) AcquireMagickMemory(sizeof(*magick_info));
    if (magick_info == (MagickInfo *) NULL)
      return 0;

    (void) ResetMagickMemory(magick_info, 0, sizeof(*magick_info));

    magick_info->decoder = JPEGDecodeImage;
    magick_info->encoder = JPEGRawImage;
    magick_info->thread_support = MagickTrue;
    magick_info->mime_type = "image/jpeg";
    magick_info->description = ConstantString("JPEG image format");
    magick_info->magick = ConstantString("JPEG");

    entry = CloneMagickInfo(magick_info);
    if (entry != (MagickInfo *) NULL)
      (void) RegisterMagickInfo(entry);

    entry = CloneMagickInfo(magick_info);
    if (entry != (MagickInfo *) NULL)
      {
        entry->magick = ConstantString("JPE");
        (void) RegisterMagickInfo(entry);
      }

    entry = CloneMagickInfo(magick_info);
    if (entry != (MagickInfo *) NULL)
      {
        entry->magick = ConstantString("JPG");
        (void) RegisterMagickInfo(entry);
      }

    entry = CloneMagickInfo(magick_info);
    if (entry != (MagickInfo *) NULL)
      {
        entry->magick = ConstantString("JPS");
        (void) RegisterMagickInfo(entry);
      }

    entry = CloneMagickInfo(magick_info);
    if (entry != (MagickInfo *) NULL)
      {
        entry->magick = ConstantString("PJPEG");
        (void) RegisterMagickInfo(entry);
      }

    length = strlen(magick_info->description) + 1;
    RelinquishMagickMemory(magick_info);
    return length;
}
